package com.stacklab.service;
import com.stacklab.dto.ApiDtos.*;import com.stacklab.entity.*;import com.stacklab.exception.NotFoundException;import com.stacklab.repository.*;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ProjectService{private final ProjectRepository projects;private final UserRepository users;private final ActivityRepository activities;private final CurrentUserService current;
 public ProjectService(ProjectRepository p,UserRepository u,ActivityRepository a,CurrentUserService c){projects=p;users=u;activities=a;current=c;}
 @Transactional public ProjectView create(ProjectInput r){AppUser m=manager(r.managerId());Project p=projects.save(new Project(r.name(),r.description(),m));activities.save(new ActivityLog(null,p,current.get(),"PROJECT_CREATED",null,null,p.getName()));return ProjectView.of(p);}
 @Transactional public ProjectView update(Long id,ProjectInput r){Project p=getEntity(id);AppUser previous=p.getManager();AppUser next=r.managerId()==null?null:manager(r.managerId());p.update(r.name(),r.description(),next,r.archived());activities.save(new ActivityLog(null,p,current.get(),"PROJECT_UPDATED","manager",previous==null?null:previous.getEmail(),next==null?null:next.getEmail()));return ProjectView.of(p);}
 @Transactional(readOnly=true) public ProjectView get(Long id){return ProjectView.of(getEntity(id));} @Transactional(readOnly=true) public Page<ProjectView> list(String q,Boolean archived,Pageable p){return projects.findAll((root,query,cb)->{java.util.List<jakarta.persistence.criteria.Predicate> conditions=new java.util.ArrayList<>();if(q!=null&&!q.isBlank())conditions.add(cb.like(cb.lower(root.get("name")),"%"+q.toLowerCase()+"%"));if(archived!=null)conditions.add(cb.equal(root.get("archived"),archived));return cb.and(conditions.toArray(jakarta.persistence.criteria.Predicate[]::new));},p).map(ProjectView::of);}
 private Project getEntity(Long id){return projects.findById(id).orElseThrow(()->new NotFoundException("Project not found"));}private AppUser manager(Long id){AppUser u=users.findById(id).orElseThrow(()->new NotFoundException("Manager not found"));if(u.getRole()!=Role.MANAGER&&u.getRole()!=Role.ADMIN)throw new IllegalArgumentException("Project manager must have MANAGER or ADMIN role");return u;}
}
